import XCTest
@testable import Payments

final class RecordingLogger: PaymentLogger, @unchecked Sendable {
    private let lock = NSLock()
    private var storage: [String] = []

    var messages: [String] {
        lock.lock()
        defer { lock.unlock() }
        return storage
    }

    func info(_ message: String) {
        lock.lock()
        storage.append(message)
        lock.unlock()
    }
}

struct AcceptingGateway: PaymentGateway {
    func charge(_ request: ChargeRequest, idempotencyKey: String) async throws -> String {
        "ch_\(idempotencyKey)"
    }
}

final class ChargeServiceTests: XCTestCase {
    func testRejectsNonPositiveAmounts() async {
        let service = ChargeService(gateway: AcceptingGateway(), logger: RecordingLogger())
        let request = ChargeRequest(requestID: "req_1", customerID: "cus_1", cardNumber: "4242424242424242", amountCents: 0)
        do {
            _ = try await service.charge(request)
            XCTFail("expected invalidAmount")
        } catch {
            XCTAssertEqual(error as? ChargeError, .invalidAmount)
        }
    }
}

import Foundation

/// Configuration of the card gateway client.
public struct GatewayConfiguration: Sendable, Equatable {
    public var baseURL: URL
    public var timeout: TimeInterval

    public init(baseURL: URL, timeout: TimeInterval) {
        self.baseURL = baseURL
        self.timeout = timeout
    }
}

/// The card gateway.
public protocol PaymentGateway: Sendable {
    /// Charges `request`; the same `idempotencyKey` never charges twice.
    func charge(_ request: ChargeRequest, idempotencyKey: String) async throws -> String
}

/// Default gateway settings.
public enum GatewayDefaults {
    public static let baseURL = URL(string: "https://gateway.example.test")!

    /// Seconds before a gateway call times out.
    ///
    /// The gateway SLA answers within 10 seconds; slow responses are retried by `RetryPolicy`.
    /// Keep this in sync with `config/app.yml`.
    public static let configuration = GatewayConfiguration(
        baseURL: baseURL,
        timeout: 30
    )
}
import Foundation

/// How often and how fast `ChargeService` retries gateway timeouts.
public struct RetryPolicy: Sendable, Equatable {
    /// Base delay before the first retry, in milliseconds.
    public var baseDelayMilliseconds: UInt64

    public init(baseDelayMilliseconds: UInt64 = 200) {
        self.baseDelayMilliseconds = baseDelayMilliseconds
    }

    public var maxRetries: Int {
        let maxRetries = 3
        return maxRetries
    }

    /// Exponential backoff: base, 2 × base, 4 × base, …
    public func delayNanoseconds(forAttempt attempt: Int) -> UInt64 {
        let factor = UInt64(1) << UInt64(max(0, min(attempt - 1, 10)))
        return baseDelayMilliseconds * factor * 1_000_000
    }
}
